INSERT INTO facility.seed_metadata(seed,data_class) VALUES (290613,'SYNTHETIC');
INSERT INTO facility.facility_master(property_id,facility_id,facility_name,facility_type,owner_team,capacity,open_hour,close_hour,is_active,is_synthetic,source_updated_at) SELECT 'SYNTHETIC_HOTEL_001',concat('FC-',leftPad(toString(number+1),2,'0')),concat('FACILITY ',toString(number+1)),multiIf(number%4=0,'POOL',number%4=1,'FITNESS',number%4=2,'SPA','LOUNGE'),multiIf(number%3=0,'LEISURE',number%3=1,'ENGINEERING','GUEST_SERVICE'),20+number*15,6,22,1,1,parseDateTime64BestEffort('2026-08-01 00:00:00.000+09:00') FROM numbers(20);
INSERT INTO facility.facility_events(property_id,event_id,facility_id,facility_user_ref,event_type,event_at,event_status,severity,duration_minutes,amount,downtime_minutes,data_period_status,is_forecast,is_synthetic,source_updated_at) SELECT 'SYNTHETIC_HOTEL_001',concat('FE-',leftPad(toString(number+1),8,'0')),concat('FC-',leftPad(toString((number*7+number*number)%20+1),2,'0')),if(number%5=0,NULL,concat('FU-',leftPad(toString((number*7919)%11475+1),8,'0'))),multiIf(number%29=0,'INCIDENT',number%17=0,'INSPECTION','USAGE'),parseDateTime64BestEffort(concat(toString(toDate('2025-01-01')+((number*37+number*number)%577)),' ',leftPad(toString(6+(number*11)%16),2,'0'),':00:00+09:00')),multiIf(number%29=0,'CLOSED',number%17=0,'COMPLETED','COMPLETED'),if(number%29=0,'MEDIUM',NULL),toFloat32(30+number%180),toDecimal64(10000+(number*97)%500000,2),if(number%29=0,least(60,30+number%180),0),'SYNTHETIC_ACTUAL_LIKE',0,1,parseDateTime64BestEffort('2026-08-01 00:00:00.000+09:00') FROM numbers(20000);
INSERT INTO facility.hotel_staffing_daily(property_id,staffing_id,business_date,department,approved_positions,scheduled_hours,worked_hours,labor_cost,fte,vacancies,new_hires,separations,data_period_status,is_forecast,is_synthetic,source_updated_at) SELECT 'SYNTHETIC_HOTEL_001',concat('ST-',leftPad(toString(day+1),3,'0'),'-',toString(dept)),toDate('2025-01-01')+day,concat('DEPT_',toString(dept)),toUInt32(8+dept%5),toFloat32(64+dept*4),toFloat32(60+dept*4),toDecimal64(1200000+dept*90000+(day%29)*10000,2),toFloat32(8+dept%5),toUInt32(dept%3),toUInt32(if((day+dept)%31=0,1,0)),toUInt32(if((day+dept)%61=0,1,0)),'SYNTHETIC_ACTUAL_LIKE',0,1,parseDateTime64BestEffort('2026-08-01 00:00:00.000+09:00') FROM (SELECT number day FROM numbers(577)) AS days CROSS JOIN (SELECT number dept FROM numbers(10)) AS departments;
INSERT INTO facility.facility_resource_daily(property_id,resource_id,business_date,resource_scope,energy_kwh,water_m3,waste_kg,resource_cost,scheduled_hours,downtime_hours,data_period_status,is_forecast,is_synthetic,source_updated_at) SELECT 'SYNTHETIC_HOTEL_001',concat('RS-',leftPad(toString(day+1),3,'0'),'-',toString(scope)),toDate('2025-01-01')+day,concat('SCOPE_',toString(scope)),toFloat64(120+scope*30+(day%17)),toFloat64(8+scope+(day%5)),toFloat64(15+scope+(day%7)),toDecimal64(50000+scope*8000+(day%29)*300,2),toFloat32(24),toFloat32(scope%5),'SYNTHETIC_ACTUAL_LIKE',0,1,parseDateTime64BestEffort('2026-08-01 00:00:00.000+09:00') FROM (SELECT number day FROM numbers(577)) AS days CROSS JOIN (SELECT number scope FROM numbers(8)) AS scopes;
